/**
 * Récupère les références croisées TSK pour un verset donné
 * @param livreId - ID du livre (ex: "gn", "mt")
 * @param chapitre - Numéro du chapitre
 * @param verset - Numéro du verset
 * @returns Tableau de références au format { livreId, chapitre, verset }
 */
export function getCrossReferences(
  livreId: string,
  chapitre: number,
  verset: number
): Array<{ livreId: string; chapitre: number; verset: number; reference: string }> {
  const key = `${livreId}-${chapitre}-${verset}`;
  const refs = TSK_CROSS_REFERENCES[key] || [];
  return refs.map((ref) => {
    // Format attendu : "gn-1-3" → livreId="gn", chapitre=1, verset=3
    const parts = ref.split("-");
    if (parts.length === 3) {
      return {
        livreId: parts[0],
        chapitre: parseInt(parts[1]),
        verset: parseInt(parts[2]),
        reference: `${parts[0]} ${parts[1]}:${parts[2]}`,
      };
    }
    return null as any;
  }).filter(Boolean);
}

